LearnANOVAOptions <- if (requireNamespace('jmvcore', quietly=TRUE)) R6::R6Class(
    'LearnANOVAOptions',
    inherit = jmvcore::Options,
    public = list(
        initialize = function(
            dep = NULL,
            factor = NULL,
            postHoc = FALSE,
            showTheory = TRUE,
            showInstructions = TRUE,
            ...) {

            super$initialize(
                package = 'learnJamovi',
                name = 'LearnANOVA',
                requiresData = TRUE,
                ...)

            private$..dep <- jmvcore::OptionVariable$new(
                'dep', dep,
                suggested = list('continuous'),
                permitted = list('numeric'))

            private$..factor <- jmvcore::OptionVariable$new(
                'factor', factor,
                suggested = list('nominal', 'ordinal'),
                permitted = list('factor'))

            private$..postHoc <- jmvcore::OptionBool$new(
                'postHoc', postHoc)

            private$..showTheory <- jmvcore::OptionBool$new(
                'showTheory', showTheory)

            private$..showInstructions <- jmvcore::OptionBool$new(
                'showInstructions', showInstructions)

            self$.addOption(private$..dep)
            self$.addOption(private$..factor)
            self$.addOption(private$..postHoc)
            self$.addOption(private$..showTheory)
            self$.addOption(private$..showInstructions)
        }),
    active = list(
        dep              = function() private$..dep$value,
        factor           = function() private$..factor$value,
        postHoc          = function() private$..postHoc$value,
        showTheory       = function() private$..showTheory$value,
        showInstructions = function() private$..showInstructions$value),
    private = list(
        ..dep              = NA,
        ..factor           = NA,
        ..postHoc          = NA,
        ..showTheory       = NA,
        ..showInstructions = NA))

