#' One-Way ANOVA
#'
#' Learn about one-way ANOVA and compare group means.
#'
#' @param data the data as a data frame
#' @param dep a string naming the dependent variable
#' @param factor a string naming the grouping factor
#' @param postHoc \code{TRUE} to compute Tukey HSD post-hoc comparisons
#' @param showTheory \code{TRUE} (default) to show the theory section
#' @param showInstructions \code{TRUE} (default) to show Jamovi instructions
#' @return A results object containing ANOVA output
#' @examples
#' LearnANOVA(data = iris, dep = "Sepal.Length", factor = "Species")
#' @export
LearnANOVA <- function(
    data,
    dep = NULL,
    factor = NULL,
    postHoc = FALSE,
    showTheory = TRUE,
    showInstructions = TRUE) {

    if (missing(data))
        data <- NULL

    options <- LearnANOVAOptions$new(
        dep = dep,
        factor = factor,
        postHoc = postHoc,
        showTheory = showTheory,
        showInstructions = showInstructions)

    analysis <- LearnANOVAClass$new(
        options = options,
        data = data)

    analysis$run()
    analysis$results
}
